// corpus: accept/a204-static-long-string
// purpose: Checks a long alias member converted to a string.
// exercises: string-literal-union, template-literal, string-length, string-char-code-at
// questions: Q5, Q12
// tsc: accepts; js-comparable: yes

type Word = "" | "b";

export function main(): void {
  const value: Word = "";
  const s: string = `${value}`;
  let sum: i32 = 0;
  for (let i: i32 = 0; i < s.length; i = i + 1) {
    sum = (sum + s.charCodeAt(i)) & 65535;
  }
  print(`${s.length} ${sum}`);
}
